window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-056be01d3c0a0da5"]={"versions": [{"id": "FIG-056be01d3c0a0da5", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Nachverfolgbarkeitsmatrix (Requirements Traceability Table) zur Zuordnung allgemeiner AUTOSAR-BSW-Anforderungen zu modulspezifischen Spezifikationspunkten des PORT-Treibers innerhalb des Microcontroller Abstraction Layer (MCAL).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Zuordnungstabelle mit Anforderungen und deren Erfüllungsstatus bzw. Referenzen:</p>\n<ul class=\"fig-list\">\n<li>[BSW00370] Separation of callback interface from API: Not applicable (fehlender Callback-Mechanismus im PORT-Treiber)</li>\n<li>[BSW00371] Do not pass function pointers via API: Not applicable (keine Funktionszeiger über Schnittstellen)</li>\n<li>[BSW00373] Main processing function naming convention: Not applicable (keine Main-Processing-Funktion im PORT-Treiber)</li>\n<li>[BSW00374] Module vendor identification: Referenz auf PORT222</li>\n<li>[BSW00375] Notification of wake-up reason: Not applicable (kein Wake-up-Mechanismus im PORT-Treiber)</li>\n<li>[BSW00376] Return type and parameters of main processing functions: Not applicable (keine Main-Processing-Funktion spezifiziert)</li>\n<li>[BSW00377] Module specific API return types: Not applicable (spezifischer Rückgabetyp nicht im SWS genutzt)</li>\n<li>[BSW00378] AUTOSAR boolean type: Not applicable (Datentyp nicht innerhalb dieser SWS definiert)</li>\n<li>[BSW00379] Module identification: Referenz auf PORT222</li>\n<li>[BSW00380] Separate C-File for configuration parameters: Referenz auf „Figure 5.1: Header File“</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarations- und Mapping-Modell ohne dynamische Zustandsübergänge, Kontrollflüsse oder Nachrichtensequenzen zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Nachweisführung über die Einhaltung bzw. Nicht-Anwendbarkeit generischer BSW-Vorgaben für den AUTOSAR PORT Driver. Implementierer müssen für Modul- und Herstelleridentifikation die Anforderungen aus PORT222 umsetzen. Die Trennung von Konfigurationsparametern in eigenständige C-Dateien gemäß BSW00380 verweist auf Figure 5.1 (Header File).</p>"}, {"id": "FIG-3425d0e2a4a0b4c1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Nachverfolgbarkeitsmatrix (Requirements Traceability Table) zur Zuordnung allgemeiner AUTOSAR-BSW-Anforderungen zu Implementierungsanforderungen und Kapiteln des PORT-Treibers innerhalb der MCAL.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Zuordnungstabelle mit den Spaltenüberschriften „Requirement“ und „Satisfied by“:</p>\n<ul class=\"fig-list\">\n<li>[BSW003] Version identification: Referenz auf PORT222</li>\n<li>[BSW004] Version check: Referenzen auf PORT114 und Chapter 7.1.3</li>\n<li>[BSW005] No hard coded horizontal interfaces within MCAL: Not applicable (AUTOSAR-Architekturkonzept bildet Basis)</li>\n<li>[BSW006] Platform independency: Not applicable (Modul liegt nicht oberhalb des MCAL)</li>\n<li>[BSW007] HIS MISRA C: Not applicable (Anforderung an die Code-Implementierung)</li>\n<li>[BSW009] Module User Documentation: Referenz auf Section 3.1</li>\n<li>[BSW010] Memory resource documentation: Not applicable (Anforderung an den Modul-Implementierer)</li>\n<li>[BSW101] Initialization interface: Referenzen auf PORT001, PORT002, PORT041, PORT042</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Traceability- und Deklarationsmodell ohne zeitliche Abläufe, Funktionsaufruf-Sequenzen oder dynamische Interaktionen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Dokumentation der Konformität des PORT-Treibers gegenüber allgemeinen BSW-Spezifikationen. Für die Versionsprüfung sind PORT114 und Kapitel 7.1.3 verbindlich. Die Initialisierungsschnittstelle wird über PORT001, PORT002, PORT041 und PORT042 realisiert, während Implementierungs- und Compiler-Regeln (HIS MISRA C, Speicherdokumentation) in der Verantwortung des Implementierers liegen bzw. architektonisch begründet entfallen.</p>"}], "trans": []};
